import os
import json
import asyncio
import base64
import uuid
import time
import modal
import subprocess
from typing import Dict, List, Optional, Any
from fastapi import FastAPI, WebSocket, Request, BackgroundTasks
from fastapi.responses import HTMLResponse, JSONResponse
from fastapi.middleware.cors import CORSMiddleware
from pydantic import BaseModel
import anthropic
import google.generativeai as genai
from pinecone import Pinecone, ServerlessSpec
from neo4j import GraphDatabase
from couchbase.cluster import Cluster
from couchbase.options import ClusterOptions, PasswordAuthenticator
from cassandra.cluster import Cluster as ScyllaCluster
from redis import Redis
import httpx

app = modal.App("autonomouside")

ide_image = (
    modal.Image.debian_slim()
    .apt_install("git", "curl", "buildessential", "libssldev", "zlib1gdev", "pkgconfig", "libffidev")
    .run_commands(
        "curl L  | sh s  daemon",
        "pip install fastapi uvicorn anthropic googlegenerativeai pineconeclient neo4j couchbase cassandradriver redis playwright pyright",
        "playwright install withdeps chromium"
    )
    .env({
        "NIX_PATH": "nixpkgs=channel:nixos24.11",
        "PATH": "/root/.nixprofile/bin:/usr/local/sbin:/usr/local/bin:/usr/sbin:/usr/bin:/sbin:/bin"
    })
)

volume = modal.Volume.from_name("workspacedata", create_if_missing=True)

class IdeBackend:
    def __init__(self):
        self.pinecone = Pinecone(api_key=os.environ["PINECONE_API_KEY"])
        self.neo4j_driver = GraphDatabase.driver(
            os.environ["NEO4J_URI"], 
            auth=(os.environ["NEO4J_USER"], os.environ["NEO4J_PASSWORD"])
        )
        self.scylla_cluster = ScyllaCluster([os.environ["SCYLLA_HOST"]])
        self.scylla_session = self.scylla_cluster.connect(os.environ["SCYLLA_KEYSPACE"])
        self.dragonfly = Redis(host=os.environ["DRAGONFLY_HOST"], port=6379, db=0)
        self.cb_cluster = Cluster(
            os.environ["COUCHBASE_URI"],
            ClusterOptions(PasswordAuthenticator(os.environ["CB_USER"], os.environ["CB_PASS"]))
        )
        self.cb_bucket = self.cb_cluster.bucket("projects")
        self.anthropic_client = anthropic.Anthropic(api_key=os.environ["ANTHROPIC_API_KEY"])
        genai.configure(api_key=os.environ["GEMINI_API_KEY"])
        self.gemini_model = genai.GenerativeModel("gemini3pro")
        self.cerebras_key = os.environ["CEREBRAS_API_KEY"]

    async def generate_plan(self, prompt: str, project_id: str):
        context = await self.get_project_context(project_id)
        response = self.anthropic_client.messages.create(
            model="claudeopus4520251101",
            max_tokens=4096,
            system="You are an expert system architect. Output a JSON DAG of tasks.",
            messages=[{"role": "user", "content": f"Context: {context}\n\nTask: {prompt}"}]
        )
        plan = json.loads(response.content.text)
        self.cb_bucket.default_collection().upsert(f"plan_{project_id}", plan)
        return plan

    async def get_project_context(self, project_id: str):
        with self.neo4j_driver.session() as session:
            result = session.run("MATCH (n)[r]>(m) WHERE n.projectId = $pid RETURN n, r, m", pid=project_id)
            graph = [record.data() for record in result]
        return {"graph": graph}

    def log_telemetry(self, project_id: str, event_type: str, data: dict):
        query = "INSERT INTO events (id, project_id, type, timestamp, payload) VALUES (?, ?, ?, ?, ?)"
        self.scylla_session.execute(query, (uuid.uuid4(), project_id, event_type, int(time.time()  1000), json.dumps(data)))

    async def fast_code_gen(self, prefix: str, suffix: str):
        async with httpx.AsyncClient() as client:
            resp = await client.post(
                "",
                headers={"Authorization": f"Bearer {self.cerebras_key}"},
                json={
                    "model": "llama3.170b",
                    "prompt": f"{prefix}<|cursor|>{suffix}",
                    "max_tokens": 128,
                    "stop": ["\n\n"]
                }
            )
            return resp.json()["choices"]["text"]

    async def run_visual_test(self, url: str):
        from playwright.async_api import async_playwright
        async with async_playwright() as p:
            browser = await p.chromium.launch()
            page = await browser.new_page()
            await page.goto(url)
            screenshot = await page.screenshot(type="png")
            await browser.close()

            vision_resp = self.gemini_model.generate_content([
                "Analyze this UI for bugs and visual inconsistencies.",
                {"mime_type": "image/png", "data": base64.b64encode(screenshot).decode()}
            ])
            return vision_resp.text

@app.function(image=ide_image, volumes={"/workspace": volume}, gpu="B200", timeout=3600)
@modal.asgi_app()
def fastapi_app():
    web_app = FastAPI()
    backend = IdeBackend()

    web_app.add_middleware(
        CORSMiddleware,
        allow_origins=[""],
        allow_methods=[""],
        allow_headers=[""],
    )

    @web_app.post("/api/plan")
    async def create_plan(req: Request):
        data = await req.json()
        return await backend.generate_plan(data["prompt"], data["project_id"])

    @web_app.post("/api/complete")
    async def code_complete(req: Request):
        data = await req.json()
        return {"suggestion": await backend.fast_code_gen(data["prefix"], data["suffix"])}

    @web_app.websocket("/ws/{project_id}")
    async def websocket_endpoint(websocket: WebSocket, project_id: str):
        await websocket.accept()
        sb = modal.Sandbox.create(
            "bash",
            image=ide_image,
            volumes={"/workspace": volume},
            app=modal.App.current()
        )

        async def handle_stream(stream, channel):
            async for data in stream:
                await websocket.send_json({"channel": channel, "data": data.decode() if isinstance(data, bytes) else data})

        asyncio.create_task(handle_stream(sb.stdout, 1))
        asyncio.create_task(handle_stream(sb.stderr, 1))

        while True:
            msg = await websocket.receive_json()
            if msg["channel"] == 1:
                sb.stdin.write(msg["data"].encode())
            elif msg["channel"] == 0:
                if msg["type"] == "resize":
                    pass

    @web_app.post("/api/deploy")
    async def deploy_to_gcp(req: Request):
        data = await req.json()
        project_id = data["project_id"]
        dockerfile = """
FROM python:3.11slim
WORKDIR /app
COPY . .
RUN pip install r requirements.txt
CMD ["python", "main.py"]
        """
        with open(f"/workspace/{project_id}/Dockerfile", "w") as f:
            f.write(dockerfile)

        subprocess.run(["gcloud", "builds", "submit", "tag", f"gcr.io/{os.environ['GCP_PROJECT']}/{project_id}", f"/workspace/{project_id}"])
        subprocess.run(["gcloud", "run", "deploy", project_id, "image", f"gcr.io/{os.environ['GCP_PROJECT']}/{project_id}", "platform", "managed"])
        return {"status": "deployed"}

    return web_app

