    <script>
        const projectId = "project" + Math.random().toString(36).substr(2, 9);
        const ws = new WebSocket(wss://${window.location.host}/ws/${projectId});
        const term = new Terminal({ theme: { background: '010409' }, fontSize: 13, fontFamily: 'monospace' });
        let editor;

        require.config({ paths: { vs: '' } });
        require(['vs/editor/editor.main'], function () {
            editor = monaco.editor.create(document.getElementById('editorcontainer'), {
                value: 'print("Hello Autonomous IDE")',
                language: 'python',
                theme: 'vsdark',
                automaticLayout: true,
                minimap: { enabled: false },
                fontSize: 14,
                fontFamily: 'Fira Code, monospace'
            });

            editor.onDidChangeModelContent(async () => {
                const prefix = editor.getModel().getValueInRange({ startLineNumber: 1, startColumn: 1, endLineNumber: editor.getPosition().lineNumber, endColumn: editor.getPosition().column });
                const suffix = editor.getModel().getValueInRange({ startLineNumber: editor.getPosition().lineNumber, startColumn: editor.getPosition().column, endLineNumber: editor.getModel().getLineCount(), endColumn: 1000 });

                if (prefix.endsWith(' ')) {
                    const res = await fetch('/api/complete', {
                        method: 'POST',
                        body: JSON.stringify({ prefix, suffix })
                    });
                    const data = await res.json();
                    console.log('Ghost text suggestion:', data.suggestion);
                }
            });
        });

        term.open(document.getElementById('terminalcontainer'));
        term.onData(data => ws.send(JSON.stringify({ channel: 1, data: data })));

        ws.onmessage = (event) => {
            const msg = JSON.parse(event.data);
            if (msg.channel === 1) term.write(msg.data);
        };

        document.getElementById('sendai').addEventListener('click', async () => {
            const prompt = document.getElementById('aiinput').value;
            const logArea = document.getElementById('agentlogs');
            logArea.innerHTML += <div class="text-blue-400">> Planning: ${prompt}</div>;

            const res = await fetch('/api/plan', {
                method: 'POST',
                headers: { 'ContentType': 'application/json' },
                body: JSON.stringify({ prompt, project_id: projectId })
            });
            const plan = await res.json();

            logArea.innerHTML += <div class="text-green-400">> Generated DAG with ${plan.tasks.length} tasks.</div>;
            plan.tasks.forEach(task => {
                logArea.innerHTML += <div class="pl-4 text-xs text-gray-500">- [${task.id}] ${task.title}</div>;
            });
        });

        window.addEventListener('resize', () => term.resize(Math.floor(window.innerWidth / 10), Math.floor(window.innerHeight / 30)));
    </script>
